-- 194_replace_decree_636_2024_amending_egyptian_accounting_standards_and_accounting_interpretation_2_carbon_credits_stored_in_english_only_as_one_mixed_row.sql
--
-- إعادة رفع قرار رئيس مجلس الوزراء رقم (636) لسنة 2024 بتعديل بعض أحكام معايير المحاسبة المصرية، مع تفسير المحاسبة المصرى رقم (2) لسنة 2024 "شهادات خفض الانبعاثات الكربونية" المرافق له،
-- بالنص العربى المنشور بالجريدة الرسمية - العدد 9 مكرر (أ) فى 3 مارس سنة 2024.
--
-- ===== الحالة السابقة (بذور 004/005/006 وما بعدها) =====
-- مخزَّن بصف واحد (article_no = 1، article_suffix_order = 0، نحو 17095 حرفاً) كله بالإنجليزية: ديباجة القرار ومواده الثلاث وتفسير المحاسبة رقم 2 كلها فى حقل واحد، وعنوان القانون فى laws ورابط official_url بالإنجليزية أيضاً
-- (رابط ملف باسم "Done_Decree_No_636-accounting-treatment-29-7.pdf")، فلا يجد البحث العربى ولا المساعد أى نص للقرار.
-- وفى آخر الصف المخزَّن ملاحظة آلية تقول إن تاريخ إصدار القرار غير مذكور فى المتن وإن اسم الملف يوحى بـ "29 يوليو 2024" وإنه غير مؤكد. وقد تبيّن من الجريدة الرسمية أن القرار نُشر فى العدد 9 مكرر (أ) بتاريخ 3 مارس 2024،
-- فتاريخ يوليو 2024 غير صحيح ولا يؤخذ به.
--
-- ===== المصدر والمنهجية =====
-- ملفان: (1) العدد 9 مكرر (أ) من الجريدة الرسمية كاملاً (76 صفحة PDF، الصفحات المطبوعة 2–77): القرار فى الصفحتين 2–3، والمعايير المرفقة 13 و17 و34 فى الصفحات 3–68، والتفسير فى الصفحات 69–77؛
-- (2) ملف التفسير منفرداً (9 صفحات ممسوحة ضوئياً بلا طبقة نصية). نُقل نص القرار والتفسير بصرياً من صور الصفحات (200 dpi، كل صفحة فى ثلاثة أشرطة مع تكبير المواضع الصغيرة)، ثم قوبل نص التفسير بالطبقة النصية الرقمية للجريدة
-- (مفاتيح الحروف لكل الفقرات ومطابقة كل الأرقام): كل حرف وكل رقم فى الطبقة النصية موجود فى النص المنقول، ولم يبق خارج المقابلة إلا الرسم البيانى (صورة بلا طبقة نصية) فنُقل بصرياً مع تكبيره.
-- أُبقى إملاء الأصل وأخطاؤه كما طُبعت: "الرسم البيانى التانى" و"فى مكان أخر" و"آية تغييرات أخرى" و"إعدام شهادات" و"ويقصد بها الاستبعاد من الدفاتر)" (قوس مغلق بلا قوس فاتح) و"مقيمة" و"اصدار" وعلامة الاقتباس المفتوحة بلا إغلاق فى "(Carbon Voluntary Market or "VCM)"،
-- وبنود الرسم البيانى بإملائه المطبوع (ياء بدل ألف مقصورة).
-- حُذفت ترويسة الصفحات وأرقامها وسطر "رئيس مجلس الوزراء" وكلمة "قرر" وتوقيع رئيس مجلس الوزراء. الأرقام لاتينية، وأُسقطت علامات التشكيل الصغيرة وأُبقى تنوين الفتح مكتوباً على الحرف قبل الألف كباقى الهجرات.
--
-- ===== تعديلات التمثيل (معلنة) =====
--   * ألصقت علامات الترقيم بما قبلها ( ، ؛ . : ) حيث طُبعت بمسافة قبلها، وحُذفت المسافة الداخلية قبل علامة الاقتباس الختامية فى المادة الأولى بعد "العملات الأجنبية"، كما فى الهجرات السابقة. لا أثر على الألفاظ.
--   * ديباجة القرار صف مستقل (article_no = 0) من "بعد الاطلاع على الدستور" إلى "وعلى ما عرضه رئيس مجلس إدارة الهيئة العامة للرقابة المالية"، وعنوان القرار فى hierarchical_location.
--   * مواد القرار الثلاث "المادة الأولى/الثانية/الثالثة" صفوف إصدار (article_suffix_order = -1) بلا hierarchical_location.
--   * أقسام التفسير العشرة (1 مقدمة، 2 التعريفات، 3 الاستخدامات، 4 نشأة وإصدار شهادات خفض الانبعاثات الكربونية، 5 نطاق المعالجة المحاسبية، 6 الإجراءات التى يجب على الإدارة اتخاذها، 7 محددات المعالجة المحاسبية، 8 المعالجة المحاسبية، 9 الإفصاح، 10 تاريخ التطبيق)
--     صفوف بأرقامها (article_no = 1..10، suffix = 0)، وعنوان التفسير "تفسير رقم (2) 2024 شهادات خفض الانبعاثات الكربونية" فى hierarchical_location لكل منها. عناوين البنود الفرعية فى القسم 8 (8-1 .. 8-6 و8-1-1 ..) بقيت أسطراً فى المتن كما طُبعت.
--   * قسم المراجع فى القسم 1 يبدأ بسطر "المراجع:" ثم المعايير الستة. وفى القسم 4 قائمتا (أ) و(ب) و(ج) ثم الرسم البيانى مكتوباً نصاً بترتيب خطواته العشر (1–10) بعد سطر توضيحى بين قوسين معقوفين
--     "[الرسم البيانى: ...]" وهو الإضافة الوحيدة من خارج الأصل فى هذا الملف، وضعت لبيان أن ما بعده نص رسم مصوَّر لا فقرات.
--
-- ===== الهيكل =====
-- 14 صفاً، 14 نسخة (version_no = 1): الديباجة (0، 0)، مواد القرار (1..3، -1)، أقسام التفسير (1..10، 0). المفتاح (1، 0) هو المفتاح المخزَّن نفسه (فلا تعيد بذرة القرار إدراج الصف القديم: إدراج laws فى البذور ON CONFLICT DO NOTHING).
--
-- ===== التاريخ والنسخ (قرار تقديرى يُراجَع) =====
-- المادة 3 تُعمل القرار "من اليوم التالى لتاريخ نشره" والنشر بالجريدة فى 3 مارس 2024، فـ effective_from = 2024-03-04 لكل الصفوف الأربعة عشر. تاريخ تطبيق التفسير نفسه (أول يناير 2025 مع السماح بالتطبيق المبكر) وارد فى متن القسم 10 ولم يُنسب إلى تاريخ النسخة.
-- لا amended_by على أى صف: لا يوجد لدينا تعديل لاحق مؤكد لهذا القرار (قرارا 115/2026 و36/2026 الواردان فى صفحة الهيئة عن الكربون لم يُراجَعا بعد على هذا الغرض).
--
-- ===== نطاق لا يعالجه هذا الملف =====
-- المعايير المرفقة 13 "آثار التغيرات فى أسعار صرف العملات الأجنبية" و17 "القوائم المالية المستقلة" و34 "الاستثمار العقارى" (الصفحات 3–68 من العدد) لا تدخل هذا الملف: ليست فى النص المخزَّن أصلاً، وهى ثلاثة معايير كاملة بنحو 66 صفحة
-- تُرفع (إن أُريد) بقرار منفصل بعد مراجعة. ولا تُمس بيانات laws (العنوان الإنجليزى ورابط الملف الإنجليزى وغياب enacted_at) وتُترك لهجرة بيانات laws المؤجلة، على أن يكون تاريخ الإصدار فيها 2024/3/3 تاريخ النشر بالجريدة لا تاريخ يوليو.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (14 صفاً بديباجة سليمة والقسم 10 موجود)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار (kind = 'pm_decision') ويفشل عند أى انحراف
-- (عدد، لفظ مغاير للأصل، أرقام أو نسب مغايرة، بقايا ترويسة أو توقيع، تاريخ سريان الصفوف، إجمالى الطول 13328 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix194$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[194] القرار 636/2024 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 14
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[194] القرار 636/2024 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[194] أُزيلت % مادة من القرار 636/2024 (صف واحد مخزن بالإنجليزية فقط (ديباجة ومواد القرار وتفسير المحاسبة رقم 2 مختلطة) مع ملاحظة تاريخ غير موثقة)', v_n;
  END IF;
END
$fix194$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار رئيس مجلس الوزراء رقم (636) لسنة 2024 بتعديل بعض أحكام معايير المحاسبة المصرية$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على الدستور؛
وعلى قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 ولائحته التنفيذية؛
وعلى قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 ولائحته التنفيذية؛
وعلى القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية؛
وعلى قرار رئيس الجمهورية رقم 269 لسنة 2018 بتشكيل الوزارة؛
وعلى قرار رئيس الجمهورية رقم 279 لسنة 2018 بتفويض رئيس مجلس الوزراء فى بعض الاختصاصات؛
وعلى قرار رئيس الجمهورية رقم 655 لسنة 2019؛
وعلى قرار رئيس مجلس الوزراء رقم 2115 لسنة 2023 بشأن إعادة تشكيل اللجنة الدائمة لمعايير المحاسبة المصرية والمعايير المصرية للمراجعة والفحص المحدود ومهام التأكد الأخرى؛
وعلى قرار وزير الاستثمار رقم 110 لسنة 2015 بشأن معايير المحاسبة المصرية؛
وعلى ما عرضه رئيس مجلس إدارة الهيئة العامة للرقابة المالية؛$b0_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
