WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, $h1$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h1$, $t1_0$1 - مقدمة$t1_0$, $b1_0$المراجع:
معيار المحاسبة المصرى رقم (1) عرض القوائم المالية.
معيار المحاسبة المصرى رقم (5) التغير فى السياسات المحاسبية والتغيرات فى التقديرات والأخطاء.
معيار المحاسبة المصرى رقم (23) الأصول غير الملموسة.
معيار المحاسبة المصرى رقم (24) الضريبية المؤجلة.
معيار المحاسبة المصرى رقم (47) الأدوات المالية.
معيار المحاسبة المصرى رقم (48) الإيرادات من العقود مع العملاء.
تم الإعلان عن إنشاء سوق الكربون الطوعى لأفريقيا فى مصر فى مؤتمر قمة المناخ (27) الذى أقيم بمدينة شرم الشيخ عام 2022 والذى توج جهود التعاون المشترك بين الهيئة العامة للرقابة المالية والبورصة المصرية ووزارة البيئة المصرية، حيث تم إطلاق أول سوق طوعى إفريقى لتداول شهادات خفض الانبعاثات الكربونية بالبورصة المصرية فى ضوء قرار مجلس الوزراء رقم 4664 لسنة 2022 بتعديل بعض أحكام اللائحة التنفيذية لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 باعتبار هذه الشهادات أداة مالية قابلة للقيد والتداول بالبورصة المصرية.$b1_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-04', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, $h2$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h2$, $t2_0$2 - التعريفات$t2_0$, $b2_0$2-1 شهادات خفض الانبعاثات الكربونية ويشار إليها بالشهادات (Carbon Credits): هى أدوات مالية قابلة للتداول تمثل مقابل وحدات خفض انبعاثات غازات الاحتباس الحراري، وتمثل كل "وحدة" طنًا من انبعاثات غاز ثانى أكسيد الكربون المكافئ، وتصدر لصالح مطور مشروع الخفض (مالك / غير مالك)، وذلك بعد الاعتماد والتحقق وفقًا لمعايير ومنهجيات خفض الانبعاثات الكربونية المعترف بها دوليًا، التى تقوم بها جهات التحقق والمصادقة سواء المحلية أو الدولية المقيدة بالقائمة المعدة لدى الهيئة لهذا الغرض.
2-2 جهات وضع المعايير والمنهجيات (Standard Programs): هى الجهات التى تضع أسس ومنهجيات قياس خفض الانبعاثات الكربونية وفقا لمنهجيات معترف بها دوليًا، ومنها منهجيات اتفاقية الأمم المتحدة الإطارية المعنية بتغير المناخ (UNFCCC) والمنهجيات المعتمدة من قبل International Carbon Reduction and Offset Alliance (ICROA) أو وفقًا للمنهجيات المعتمدة محليًا من الجهات الحكومية المختصة فى هذا الشأن.
2-3 سجلات الكربون الطوعية (Carbon Credits Registries): هى أنظمة حفظ مركزية إلكترونية تتضمن سجلات لإصدار وتسجيل وتتبع تسلسل نقل ملكية شهادات خفض الانبعاثات الكربونية والناتجة عن تنفيذ مشروعات خفض الانبعاثات الكربونية التى تم تنفيذها وفقًا للمنهجيات الصادرة عن جهات وضع المعايير والمنهجيات (Standard Programs).
2-4 الجهات منشأة سجلات الكربون الطوعية: هى الجهات المالكة والقائمة على حفظ وإدارة سجلات الكربون الطوعية.
2-5 جهات التحقق والمصادقة (Validation and Verification Bodies): هى الجهات التى تقوم بعمليات التحقق والمصادقة من خلال مراجعة والتحقق من مطابقة المشروع لمتطلبات معايير ومنهجيات الخفض المعتمدة لدى جهات وضع المعايير والمنهجيات.
2-6 التجار (Traders): التجار الذين يتعاملون على شهادات خفض الانبعاثات الكربونية بيعًا وشراءً مقابل عمولة.
2-7 مطورى المشروعات (Project Developers): وهى الجهات المسئولة عن تنفيذ مشروعات خفض الانبعاثات الكربونية التى يتم بموجبها إصدار شهادات خفض الانبعاثات الكربونية بسجلات الكربون الطوعية بعد اعتماد جهات التحقق والمصادقة وقد يكون مطور المشروع هو مالك المشروع أساسا وقد يكون المطور جهة غير مالكة للمشروع (يقوم بتمويل / تنفيذ المشروع مقابل حصة محددة من شهادات خفض الانبعاثات الكربونية يتم الاتفاق عليها مع المالك).$b2_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-04', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
