WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, $h4$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h4$, $t4_0$4 - نشأة وإصدار شهادات خفض الانبعاثات الكربونية$t4_0$, $b4_0$يمكن تلخيص دورة إصدار شهادات خفض الانبعاثات الكربونية فى سوق الكربون الطوعى "VCM" على النحو التالى:
(أ) نشأة شهادات خفض الانبعاثات الكربونية:
1- يقوم مطور مشروع خفض الانبعاثات الكربونية (مالك) أو غير مالك المشروع بإعداد وثيقة تصميم المشروع وفقا لأحد سجلات الكربون الطوعية المعتمدة لدى الجهات الرقابية المعتمدة.
2- يقوم المطور باختيار أحد جهات التحقق والمصادقة المعتمدة لدى سجل الكربون الطوعى للمشروع والمرخص لها من الجهات الرقابية للقيام بأعمال التحقق والمصادقة لمشروع الخفض.
3- يقوم مطور المشروع بتسجيل المشروع لدى سجل الكربون الطوعى بعد انتهاء عملية المصادقة.
4- يقوم مطور المشروع بتنفيذ مشروع الخفض.
5- يتم التحقق من صحة المشروع من قبل جهة التحقق التى تم اختيارها.
6- يتم إصدار شهادات خفض الانبعاثات الكربونية من خلال سجل الكربون لصالح مطور المشروع.
(ب) تداول شهادات خفض الانبعاثات الكربونية: تكون شهادات خفض الانبعاثات الكربونية قابلة للتداول أو التحويل بين الحسابات فى السجل نفسه، ويمكن نقل ملكية الشهادات من مطور المشروع إلى التجار والمستخدمين النهائيين وذلك خلال الأسواق الطوعية لتداول شهادات خفض الانبعاثات الكربونية.
(ج) إعدام شهادات خفض الانبعاثات الكربونية ويقصد بها الاستبعاد من الدفاتر): عند استخدام شهادات خفض الانبعاثات الكربونية لتخفيض انبعاثات المنشأة، يقوم المستخدم النهائى بإصدار تعليمات إلى السجل بإعدام تلك الشهادات مما يترتب عليه منع استخدام أو تداول هذه الشهادات مرة أخرى من قبل أى كيان آخر.
ويوضح الرسم البيانى التانى دورة إصدار شهادات خفض الانبعاثات الكربونية والأطراف المعنية بشكل مبسط.
[الرسم البيانى: دورة إصدار شهادات خفض الانبعاثات الكربونية، مكتوب نصًا بترتيب خطواته المرقمة]
1- التخطيط لمشروع الخفض
2- تصميم مشروع الخفض (مطوري المشروع سواءً كان ممولًا بذاتهم أو من خلال ممول خارجي)
3- المصادقة على وثيقة تصميم المشروع (من خلال جهات التحقق والمصادقة المعتمدة)
4- تسجيل المشروع في أحد سجلات الكربون الطوعية (من خلال سجلات الكربون)
5- تنفيذ مشروع الخفض (مطوري المشروع)
6- المراقبة
7- التحقق من المشروع (من خلال جهات التحقق المعتمدة من سجلات)
8- إصدار شهادات خفض الانبعاثات الكربونية
9- تداول الشهادات (أسواق التداول مثل سوق تداول شهادات خفض الانبعاثات الكربونية الذي تم تدشينه في مصر)
10- تعويض الانبعاثات (مشتري الشهادات)$b4_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-04', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, $h5$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h5$, $t5_0$5 - نطاق المعالجة المحاسبية$t5_0$, $b5_0$تختلف المعالجات المحاسبية وفقا لطبيعة الترتيب والغرض التجارى لشراء الشهادات أو إصدارها من قبل مطورى المشروع، ومن ثم يجب على الشركات تحديد الحقائق والتعرف على الظروف المختلفة لتحديد المعالجة المحاسبية المناسبة والمعيار المحاسبى الواجب تطبيقه.
إن طبيعة الترتيب والغرض التجارى لشراء هذه الأرصدة غالبًا ما يكون أساس المعالجة المحاسبية، بما فى ذلك المعيار المحاسبى الواجب تطبيقه.$b5_0$
