WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, $h8$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h8$, $t8_0$8 - المعالجة المحاسبية$t8_0$, $b8_0$8-1 حالة إصدار الشهادة لصالح مطور مشروع خفض الانبعاثات الكربونية حالة كونه المالك له.
8-1-1 القياس الأولى:
(أ) يتم الاعتراف بقيمة شهادات خفض الانبعاثات الكربونية عند اصدار الشهادات لصالح المنشئ / مالك المشروع مباشرة، والتى سيتم إلغاؤها لتحقيق التبادل الكربونى (فقط) من اجل الاستخدام الداخلى ضمن الأصول غير الملموسة وتضاف قيمتها الى حقوق الملكية تحت بند احتياطى شهادات خفض الانبعاثات الكربونية على أساس التكلفة الفعلية.
(ب) أما التى سوف يتم التصرف فيها بالبيع فإنها تثبت وفقا لمعيار المحاسبة المصرى رقم (47) الأدوات المالية على أساس التكلفة الفعلية.
8-1-2 القياس اللاحق:
(أ) تخضع للقياس اللاحق فى الحالة (أ) أعلاه وفقا لمتطلبات معيار المحاسبة المصرى رقم (23) الأصول غير الملموسة، ويجب مراعاة أن يتم تخفيض احتياطى شهادات خفض الانبعاثات الكربونية بالقدر الذى يعكس الاستهلاك أو الاضمحلال فى الأصول غير الملموسة المرتبطة بالقياس لشهادات خفض الانبعاثات الكربونية.
(ب) وتخضع شهادات خفض الانبعاثات الكربونية فى الحالة (ب) أعلاه القياس اللاحق لها ( والتى تم تبويبها فى القياس الأولى كأدوات مالية)، وفقًا لمعيار المحاسبة المصرى رقم (47) الأدوات المالية تحت بند أدوات مالية مقيمة بالقيمة العادلة من خلال الدخل الشامل، ويجوز فى حالة قيد تلك الشهادات بسوق تداول شهادات خفض الانبعاثات الكربونية بالبورصة المصرية على انها أدوات مالية مقيمة بالقيمة العادلة من خلال الأرباح أو الخسائر.
8-1-3 الاستبعاد من الدفاتر:
(أ) فى حالة استبعاد أرصدة شهادات خفض الانبعاثات الكربونية لتحقيق التبادل الكربونى (فى حالة استخدامها داخليا) يتم تسوية الأرصدة الخاصة بها ضمن احتياطى شهادات خفض الانبعاثات الكربونية، ويتم التسوية النهائية إلى حساب الأرباح / الخسائر المرحلة.
(ب) أما فى حالة استبعاد أرصدة شهادات خفض الانبعاثات الكربونية (فى حالة نية التصرف فيها بالبيع)، فأنه يتم تسوية الأرصدة الخاصة وفقا الى قواعد استبعاد الأدوات المالية كما ورد بمعيار المحاسبة المصرى رقم (47).
8-2 حالة إصدار الشهادات لصالح مطور أو ممول مشروع خفض الانبعاثات الكربونية ولكنه ليس المالك للمشروع.
8-2-1 القياس الأولى:
وفقا لما تم تناوله فى الفقرات السابقة، وفى حالة اصدار شهادات خفض الانبعاثات الكربونية لصالح مطور أو ممول مشروع، فإنه يتم أثباتها كأدوات مالية وفقا لمعيار المحاسبة المصرى رقم (47) على أساس التكلفة الفعلية.
8-2-2 القياس اللاحق:
تخضع شهادات خفض الانبعاثات الكربونية فى القياس اللاحق لها وفقا لمعيار المحاسبة المصرى رقم (47) الأدوات المالية تحت بند أدوات مالية مقيمة بالقيمة العادلة من خلال الدخل الشامل، ويجوز فى حالة قيد تلك الشهادات بسوق تداول شهادات خفض الانبعاثات الكربونية بالبورصات المصرية على انها أدوات مالية مقيمة بالقيمة العادلة من خلال الأرباح أو الخسائر.
8-2-3 الاستبعاد من الدفاتر:
فى حالة استبعاد أرصدة شهادات خفض الانبعاثات الكربونية يتم تسوية الأرصدة الخاصة وفقا لقواعد استبعاد الأدوات المالية كما ورد بمعيار المحاسبة رقم (47).
8-3 حالة شراء شهادات خفض الانبعاثات الكربونية بهدف تحقيق التبادل الكربونى (الاستخدام الداخلى لها والغائها).
8-3-1 القياس الأولى:
فى حالة شراء شهادات خفض الانبعاثات الكربونية بهدف لتحقيق التبادل الكربونى (الاستخدام الداخلى لها وإلغائها - Offsetting)، فإنها تثبت بتكلفة الاقتناء لها شاملا كافة المصروفات والرسوم التى تكبدتها المنشأة لاقتناء تلك الشهادات وتعالج وفقا لمعيار المحاسبة المصرى رقم (23) الأصول غير الملموسة.
8-3-2 القياس اللاحق:
تخضع للقياس اللاحق فى هذه الحالة وفقا لمتطلبات معيار الأصول غير الملموسة رقم (23)، ويتم استهلاكها أو إلغاؤها على أساس سياسة الشركة وطبيعة تلك الشهادات.
8-3-3 الاستبعاد من الدفاتر:
فى حالة استبعاد أرصدة شهادات خفض الانبعاثات الكربونية يتم تسوية الأرصدة الخاصة بها وتسوية أرصدة الأصول غير الملموسة ومعالجة الفرق فى الأرباح / الخسائر المرحلة.
8-4 حالة شراء شهادات خفض الانبعاثات الكربونية بهدف المتاجرة فيها.
8-4-1 القياس الأولى:
فى حالة شراء شهادات خفض الانبعاثات الكربونية بهدف المتاجرة فيها، فإنها تثبت بتكلفة الاقتناء لها شاملا كافة المصروفات والرسوم التى تكبدتها المنشأة لاقتناء تلك الشهادات، وتعالج وفقا لمعيار المحاسبة المصرى رقم (47) الأدوات المالية.
8-4-2 القياس اللاحق:
وتخضع شهادات خفض الانبعاثات الكربونية فى القياس اللاحق لها وفقا لمعيار المحاسبة المصرى رقم (47) الأدوات المالية تحت بند أدوات مالية مقيمة بالقيمة العادلة من خلال الدخل الشامل، ويجوز فى حالة قيد تلك الشهادات بسوق تداول شهادات خفض الانبعاثات الكربونية بالبورصات المصرية على انها أدوات مالية مقيمة بالقيمة العادلة من خلال الأرباح أو الخسائر.
8-4-3 الاستبعاد من الدفاتر:
فى حالة استبعاد أرصدة شهادات خفض الانبعاثات الكربونية يتم تسوية الأرصدة الخاصة بها وفقا الى قواعد استبعاد الأدوات المالية كما ورد بمعيار المحاسبة المصرى رقم (47).
8-5 المعالجة الضريبية:
يراعى تطبيق متطلبات معيار المحاسبة المصرى رقم (24) ضرائب الدخل على الحالات السابقة.
8-6 حالات خاصة:
فى حالة تغيير الغرض من اقتناء الشهادات.
يتم مراعاة تطبيق معيار المحاسبة المصرى التغير فى السياسات المحاسبية والتغيرات فى التقديرات والأخطاء - معيار المحاسبة المصرى رقم (5) وتسوية الأرصدة فى ضوء ذلك.$b8_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-03-04', 'active' FROM ins8_0;

WITH ins9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, $h9$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h9$, $t9_0$9 - الإفصاح$t9_0$, $b9_0$تلتزم الشركة بالإفصاح ضمن الإيضاحات المتممة للقوائم المالية عن:
معلومات تتعلق بالسياسة المحاسبية المحددة التى تطبقها المنشأة بما يتفق مع ما سبق عرضه.
معلومات إضافية لم تعرض فى مكان أخر فى القوائم المالية إلا أنها ذات صلة ولازمة لتفهم المعلومات المالية وغير المالية المتعلقة بشهادات خفض الانبعاثات الكربونية.
طرق التقييم المتبعة وأسس التسعير وطبيعتها التى استخدمت فى تقييم شهادات خفض الانبعاثات الكربونية.
طرق الإهلاك المستخدمة، والأعمار الإنتاجية المعترف بها ضمن بنود الأصول غير الملموسة.
أثر التغير فى السياسات المحاسبية المتبعة إن وجدت وفقا للافصاحات المطلوبة بمعيار المحاسبة المصرى رقم (5) السياسات المحاسبية والتغيرات فى التقديرات والأخطاء.
قيمة الإضافات أو الاستبعادات التى تمت خلال الفترة لشهادات خفض الانبعاثات الكربونية وأسبابها وأثرها على القوائم المالية للشركة.
تسوية بين قيم شهادات خفض الانبعاثات الكربونية فى بداية ونهاية الفترة تبين ما يلى:
الإضافات أو الاستبعادات من الدفاتر.
الزيادات أو الانخفاضات الناتجة من عمليات إعادة التقييم، وعن خسائر الاضمحلال المعترف بها أو المرتدة خلال الفترة.
آية تغييرات أخرى.$b9_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
