SELECT id, 1, body, '2024-03-04', 'active' FROM ins9_0;

WITH ins10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, $h10$تفسير رقم (2) 2024 "شهادات خفض الانبعاثات الكربونية" (تفسير محاسبة مصرى مرافق لقرار رئيس مجلس الوزراء رقم (636) لسنة 2024)$h10$, $t10_0$10 - تاريخ التطبيق$t10_0$, $b10_0$يبدأ التطبيق فى أو بعد أول يناير 2025، ويسمح بالتطبيق المبكر، وإذا قامت المنشأة بالتطبيق المبكر يجب الإفصاح عن ذلك.$b10_0$
  FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
