SELECT id, 1, body, '2024-03-04', 'active' FROM ins10_0;

DO $verify194$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 636 AND law_year = 2024 AND kind = 'pm_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[194] القرار 636/2024 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 14 THEN RAISE EXCEPTION '[194] عدد المواد % بدل 14', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2024-03-04';
  IF v_v <> 14 THEN RAISE EXCEPTION '[194] عدد النسخ % بدل 14', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%العدد 9 مكرر%' OR body LIKE '%فى 3 مارس سنة%' OR body LIKE '%مدبولى%' OR body LIKE '%دكتور /%' OR body LIKE '%FINANCIAL REGULATORY%' OR body LIKE '%WWW.FRA%' OR body LIKE '%رررر%' OR body LIKE '%ا ً%' OR body LIKE '%�%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[194] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على الدستور؛%' AND body LIKE '%ر رئيس الجمهورية رقم 279 لسنة 2018 ب%' AND body LIKE '%الهيئة العامة للرقابة المالية؛' AND body LIKE '% بالقانون رقم 159 لسنة 1981 ولا%' AND body LIKE '% رقم 159 لسنة 1981 ولائحته التنف%' AND body LIKE '% بالقانون رقم 95 لسنة 1992 ولا%' AND body LIKE '%ن رقم 95 لسنة 1992 ولائحته التنف%' AND body LIKE '%ى القانون رقم 10 لسنة 2009 بتن%' AND body LIKE '%ن رقم 10 لسنة 2009 بتنظيم الرقاب%' AND body LIKE '%الجمهورية رقم 269 لسنة 2018 بتش%' AND body LIKE '% رقم 269 لسنة 2018 بتشكيل الوزار%' AND body LIKE '%الجمهورية رقم 279 لسنة 2018 بتف%' AND body LIKE '% رقم 279 لسنة 2018 بتفويض رئيس م%' AND body LIKE '%الجمهورية رقم 655 لسنة 2019؛%' AND body LIKE '% رقم 655 لسنة 2019؛%' AND body LIKE '%س الوزراء رقم 2115 لسنة 2023 بشأ%' AND body LIKE '%رقم 2115 لسنة 2023 بشأن إعادة تش%' AND body LIKE '%الاستثمار رقم 110 لسنة 2015 بشأ%' AND body LIKE '% رقم 110 لسنة 2015 بشأن معايير ا%') THEN RAISE EXCEPTION '[194] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = -1 AND body LIKE 'يستبدل بالمعايير أرقام (13) "آثار ال%' AND body LIKE '%المعايير أرقام (13) "آثار التغيرات ف%' AND body LIKE '%المعايير المرافقة لهذا القرار.' AND body LIKE '%معايير أرقام (13) "آثار التغير%' AND body LIKE '% الأجنبية"، و(17) "القوائم الم%' AND body LIKE '% المستقلة"، و(34) "الاستثمار ا%') THEN RAISE EXCEPTION '[194] مادة الإصدار 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = -1 AND body LIKE 'يضاف إلى معايير المحاسبة المصرية الم%' AND body LIKE '% معايير المحاسبة المصرية المشار إليه%' AND body LIKE '%لكربونية" المرافق لهذا القرار.' AND body LIKE '%سبة مصرى رقم (2) "شهادات خفض %') THEN RAISE EXCEPTION '[194] مادة الإصدار 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = -1 AND body LIKE 'ينشر هذا القرار فى الجريدة الرسمية، %' AND body LIKE '% القرار فى الجريدة الرسمية، ويعمل به%' AND body LIKE '%ه من اليوم التالى لتاريخ نشره.') THEN RAISE EXCEPTION '[194] مادة الإصدار 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'المراجع:%' AND body LIKE '%محاسبة المصرى رقم (24) الضريبية المؤ%' AND body LIKE '%قيد والتداول بالبورصة المصرية.' AND body LIKE '%ة المصرى رقم (1) عرض القوائم %' AND body LIKE '%ة المصرى رقم (5) التغير فى ال%' AND body LIKE '%ة المصرى رقم (23) الأصول غير ا%' AND body LIKE '%ة المصرى رقم (24) الضريبية الم%' AND body LIKE '%ة المصرى رقم (47) الأدوات الما%' AND body LIKE '%ة المصرى رقم (48) الإيرادات من%' AND body LIKE '%ر قمة المناخ (27) الذى أقيم بم%' AND body LIKE '%شرم الشيخ عام 2022 والذى توج جهو%' AND body LIKE '%س الوزراء رقم 4664 لسنة 2022 بتع%' AND body LIKE '%رقم 4664 لسنة 2022 بتعديل بعض أح%' AND body LIKE '% بالقانون رقم 95 لسنة 1992 باع%' AND body LIKE '%ن رقم 95 لسنة 1992 باعتبار هذه ا%') THEN RAISE EXCEPTION '[194] القسم 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE '2-1 شهادات خفض الانبعاثات الكربونية %' AND body LIKE '%ات منشأة سجلات الكربون الطوعية: هى ا%' AND body LIKE '% يتم الاتفاق عليها مع المالك).' AND body LIKE '%2-1 شهادات خفض ال%' AND body LIKE '%2-2 جهات وضع المع%' AND body LIKE '%2-3 سجلات الكربون%' AND body LIKE '%2-4 الجهات منشأة %' AND body LIKE '%2-5 جهات التحقق و%' AND body LIKE '%2-6 التجار (Trade%' AND body LIKE '%2-7 مطورى المشروع%') THEN RAISE EXCEPTION '[194] القسم 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'يمكن للشركات استخدام شهادات خفض الان%' AND body LIKE '%ركات استخدام شهادات خفض الانبعاثات ا%' AND body LIKE '%rbon Voluntary Market or "VCM)') THEN RAISE EXCEPTION '[194] القسم 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'يمكن تلخيص دورة إصدار شهادات خفض الا%' AND body LIKE '%لبيانى: دورة إصدار شهادات خفض الانبع%' AND body LIKE '%يض الانبعاثات (مشتري الشهادات)') THEN RAISE EXCEPTION '[194] القسم 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تختلف المعالجات المحاسبية وفقا لطبيع%' AND body LIKE '% الترتيب والغرض التجارى لشراء هذه ال%' AND body LIKE '%لمعيار المحاسبى الواجب تطبيقه.') THEN RAISE EXCEPTION '[194] القسم 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE '(أ) فهم دورة إصدار شهادات خفض الانبع%' AND body LIKE '%د تصنيف شهادات خفض الانبعاثات الكربو%' AND body LIKE '%ياسات المحاسبية المطبقة عليها.') THEN RAISE EXCEPTION '[194] القسم 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'تتحدد المعالجة المحاسبية على ضوء طبي%' AND body LIKE '% اصدار الشهادات لصالح مطور أو ممول م%' AND body LIKE '% الكربونية بهدف المتاجرة فيها.') THEN RAISE EXCEPTION '[194] القسم 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE '8-1 حالة إصدار الشهادة لصالح مطور مش%' AND body LIKE '%قياس الأولى:%' AND body LIKE '%(5) وتسوية الأرصدة فى ضوء ذلك.' AND body LIKE '%8-1 حالة إصدار ال%' AND body LIKE '%8-1-1 القياس الأو%' AND body LIKE '%8-1-1 القياس الأولى%' AND body LIKE '%ة المصرى رقم (47) الأدوات الما%' AND body LIKE '%8-1-2 القياس اللا%' AND body LIKE '%8-1-2 القياس اللاحق%' AND body LIKE '%ة المصرى رقم (23) الأصول غير ا%' AND body LIKE '%8-1-3 الاستبعاد م%' AND body LIKE '%8-1-3 الاستبعاد من %' AND body LIKE '%ة المصرى رقم (47).%' AND body LIKE '%8-2 حالة إصدار ال%' AND body LIKE '%8-2-1 القياس الأو%' AND body LIKE '%8-2-1 القياس الأولى%' AND body LIKE '%ة المصرى رقم (47) على أساس الت%' AND body LIKE '%8-2-2 القياس اللا%' AND body LIKE '%8-2-2 القياس اللاحق%' AND body LIKE '%8-2-3 الاستبعاد م%' AND body LIKE '%8-2-3 الاستبعاد من %' AND body LIKE '%المحاسبة رقم (47).%' AND body LIKE '%8-3 حالة شراء شها%' AND body LIKE '%8-3-1 القياس الأو%' AND body LIKE '%8-3-1 القياس الأولى%' AND body LIKE '%8-3-2 القياس اللا%' AND body LIKE '%8-3-2 القياس اللاحق%' AND body LIKE '%الملموسة رقم (23)، ويتم استهلا%' AND body LIKE '%8-3-3 الاستبعاد م%' AND body LIKE '%8-3-3 الاستبعاد من %' AND body LIKE '%8-4 حالة شراء شها%' AND body LIKE '%8-4-1 القياس الأو%' AND body LIKE '%8-4-1 القياس الأولى%' AND body LIKE '%8-4-2 القياس اللا%' AND body LIKE '%8-4-2 القياس اللاحق%' AND body LIKE '%8-4-3 الاستبعاد م%' AND body LIKE '%8-4-3 الاستبعاد من %' AND body LIKE '%8-5 المعالجة الضر%' AND body LIKE '%ة المصرى رقم (24) ضرائب الدخل %' AND body LIKE '%8-6 حالات خاصة:%' AND body LIKE '%ة المصرى رقم (5) وتسوية الأرص%') THEN RAISE EXCEPTION '[194] القسم 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركة بالإفصاح ضمن الإيضاحات %' AND body LIKE '%ير فى السياسات المحاسبية المتبعة إن %' AND body LIKE '%آية تغييرات أخرى.' AND body LIKE '%ة المصرى رقم (5) السياسات الم%') THEN RAISE EXCEPTION '[194] القسم 9 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE 'يبدأ التطبيق فى أو بعد أول يناير 202%' AND body LIKE '%طبيق فى أو بعد أول يناير 2025، ويسمح%' AND body LIKE '%بيق المبكر يجب الإفصاح عن ذلك.' AND body LIKE '%بعد أول يناير 2025، ويسمح بالتطب%') THEN RAISE EXCEPTION '[194] القسم 10 غير سليم'; END IF;
  IF v_len <> 13328 THEN RAISE EXCEPTION '[194] إجمالى طول المواد % بدل 13328', v_len; END IF;
  RAISE NOTICE '[194] القرار 636/2024: 14 مواد و14 نسخ، إجمالى % حرف', v_len;
